action.command:
cd /workspace && docker exec -i sva-studio-postgres psql -U sva -d sva_studio <<'SQL'
SELECT c.relname, c.relrowsecurity, c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON c.relnamespace=n.oid WHERE n.nspname='graphile_worker' AND c.relkind='r';
SELECT policyname, permissive, roles, qual FROM pg_policies WHERE tablename LIKE '%_private%';
SELECT current_setting('role');
SQL

